var reTrimMentionText = regexp.MustCompile(`@[^ ]*`)

type LarkMessage larkim.EventMessage

func (m LarkMessage) ID() string {
	return *m.MessageId
}

func (m LarkMessage) IsMentionAt(name string) bool {

	for _, mention := range m.Mentions {

		if *mention.Name == name {
			return true
		}
	}

	return false
}

func (m LarkMessage) GetChatType() consts.ChatType {
	return consts.ChatType(*m.ChatType)
}

func (m LarkMessage) GetText() string {

	content := m.parseContent()

	return strings.TrimSpace(content)
}

func (m LarkMessage) parseContent() string {
	content := *m.Content

	//"{\"text\":\"@_user_1  hahaha\"}",
	//only get text content hahaha
	var contentMap map[string]interface{}
	err := json.Unmarshal([]byte(content), &contentMap)
	if err != nil {
		fmt.Println(err)
	}
	if contentMap["text"] == nil {
		return ""
	}
	text := contentMap["text"].(string)
	return m.trimMentionText(text)
}

func (m LarkMessage) trimMentionText(msg string) string {
	//replace @到下一个非空的字段 为 ''
	return reTrimMentionText.ReplaceAllString(msg, "")
}

package domain

import (
	"context"
	"errors"

	"github.com/sirupsen/logrus"
)

type FeishuEx struct {
	actions  []Action
	feishuer Feishuer
}

type FeishuExOption func(*FeishuEx)

// WithAction 添加单个处理流程
func WithAction(action Action) FeishuExOption {
	return func(fe *FeishuEx) {
		fe.actions = append(fe.actions, action)
	}
}

// WithActions 添加多个处理流程
func WithActions(actions ...Action) FeishuExOption {
	return func(fe *FeishuEx) {
		fe.actions = append(fe.actions, actions...)
	}
}

func NewFeishuEx(feishuer Feishuer, opts ...FeishuExOption) (*FeishuEx, error) {
	feishuEx := &FeishuEx{
		feishuer: feishuer,
		actions:  make([]Action, 0, 8),
	}

	for _, opt := range opts {
		opt(feishuEx)
	}

	if err := feishuEx.checkInitSucc(); err != nil {
		return nil, err
	}

	return feishuEx, nil
}

func (f *FeishuEx) checkInitSucc() error {
	if len(f.actions) == 0 {
		return errors.New("empty actions")
	}

	return nil
}

func (f *FeishuEx) HandleMessageReceive(ctx context.Context, msg *LarkMessage) error {
	actionInfo := f.makeActionInfo(msg)

	if err := f.processActionInfo(ctx, actionInfo); err != nil {
		logrus.Errorf("process action_info error: %v", err)
		return err
	}

	return f.sendReplyMessage(ctx, actionInfo.Result)
}

func (f *FeishuEx) makeActionInfo(msg *LarkMessage) *ActionInfo {
	return &ActionInfo{
		Message: msg,
	}
}

func (f *FeishuEx) processActionInfo(ctx context.Context, actionInfo *ActionInfo) error {

	for _, action := range f.actions {
		next, err := action.Execute(ctx, actionInfo)
		if err != nil {
			logrus.Errorf("action execute error: %v", err)
			return err
		}
		if !next {
			return nil
		}

		if actionInfo.ExistsResult() {
			return nil
		}
	}

	return nil
}

func (f *FeishuEx) sendReplyMessage(ctx context.Context, actionResult *ActionResult) error {
	// NOTE(zy): 这里有可能是没有结果，也有可能是重复消息处理。
	if actionResult == nil {
		logrus.Warnf("sendReplyMessage: reply failed, nil reply message")
		return nil
	}

	return f.feishuer.Reply(ctx, actionResult)
}

package feishu

import (
	"encoding/json"
	"strings"

	"github.com/google/uuid"
	larkcard "github.com/larksuite/oapi-sdk-go/v3/card"
	larkim "github.com/larksuite/oapi-sdk-go/v3/service/im/v1"
)

// type ReplyMessage larkim.ReplyMessageReq

func MakeSimpleReply(replyMessageID string, message string) *larkim.ReplyMessageReq {

	content := larkim.NewTextMsgBuilder().
		Text(message).Build()

	reply := larkim.NewReplyMessageReqBuilder().
		MessageId(replyMessageID).Body(
		larkim.NewReplyMessageReqBodyBuilder().
			MsgType(larkim.MsgTypeText).
			Uuid(uuid.New().String()).
			Content(content).
			Build()).
		Build()

	return reply
}

func MakeSendHelpCard(messageID string) *larkim.ReplyMessageReq {

	newCardContent, _ := newSendCard(
		withHeader("🎒需要帮助吗？", larkcard.TemplateBlue),
		withMainMd("**我是万能的机器人**"),
	)

	reply := larkim.NewReplyMessageReqBuilder().
		MessageId(messageID).
		Body(larkim.NewReplyMessageReqBodyBuilder().
			MsgType(larkim.MsgTypeInteractive).
			Uuid(uuid.New().String()).
			Content(newCardContent).
			Build()).
		Build()

	return reply
}

func newSendCard(header *larkcard.MessageCardHeader, elements ...larkcard.MessageCardElement) (string, error) {

	config := larkcard.NewMessageCardConfig().
		WideScreenMode(false).
		EnableForward(true).
		UpdateMulti(false).
		Build()

	// 卡片消息体
	cardContent, err := larkcard.NewMessageCard().
		Config(config).
		Header(header).
		Elements(elements).
		String()
	return cardContent, err
}

// withSplitLine 用于生成分割线
func withSplitLine() larkcard.MessageCardElement {
	splitLine := larkcard.NewMessageCardHr().
		Build()
	return splitLine
}

// withHeader 用于生成消息头
func withHeader(title string, color string) *larkcard.
	MessageCardHeader {
	if title == "" {
		title = "🤖️机器人提醒"
	}
	header := larkcard.NewMessageCardHeader().
		Template(color).
		Title(larkcard.NewMessageCardPlainText().
			Content(title).
			Build()).
		Build()
	return header
}

// withNote 用于生成纯文本脚注
func withNote(note string) larkcard.MessageCardElement {
	noteElement := larkcard.NewMessageCardNote().
		Elements([]larkcard.MessageCardNoteElement{larkcard.NewMessageCardPlainText().
			Content(note).
			Build()}).
		Build()
	return noteElement
}

// withMainMd 用于生成markdown消息体
func withMainMd(msg string) larkcard.MessageCardElement {
	msg, i := processMessage(msg)
	msg = processNewLine(msg)
	if i != nil {
		return nil
	}
	mainElement := larkcard.NewMessageCardDiv().
		Fields([]*larkcard.MessageCardField{larkcard.NewMessageCardField().
			Text(larkcard.NewMessageCardLarkMd().
				Content(msg).
				Build()).
			IsShort(true).
			Build()}).
		Build()
	return mainElement
}

func processMessage(msg interface{}) (string, error) {
	msg = strings.TrimSpace(msg.(string))
	msgB, err := json.Marshal(msg)
	if err != nil {
		return "", err
	}

	msgStr := string(msgB)

	if len(msgStr) >= 2 {
		msgStr = msgStr[1 : len(msgStr)-1]
	}
	return msgStr, nil
}

func processNewLine(msg string) string {
	return strings.Replace(msg, "\\n", `
`, -1)
}

package chatgpt

import (
	"context"
	"errors"

	"github.com/ConnectAI-E/Feishu-EX-ChatGPT/internal/domain"

	"github.com/sashabaranov/go-openai"
)

var _ domain.LLMer = &ChatGPT{}

type ChatGPT struct {
	model  string
	client *openai.Client
}

type ChatGPTOption func(c *ChatGPT)

func WithModel(model string) ChatGPTOption {
	return func(c *ChatGPT) {
		c.model = model
	}
}

func NewChatGPT(client *openai.Client, opts ...ChatGPTOption) *ChatGPT {

	chat := &ChatGPT{
		model:  openai.GPT3Dot5Turbo,
		client: client,
	}

	for _, opt := range opts {
		opt(chat)
	}

	return chat
}

func (c ChatGPT) Chat(ctx context.Context, messages []domain.LlmMessage) (*domain.LlmAnswer, error) {

	chatGPTMessages := c.makeChatGPTMessage(messages)

	return c.send(ctx, chatGPTMessages)
}

func (c ChatGPT) makeChatGPTMessage(messages []domain.LlmMessage) []openai.ChatCompletionMessage {

	chatGPTMessages := make([]openai.ChatCompletionMessage, 0, len(messages))
	for _, m := range messages {
		chatGPTMessages = append(chatGPTMessages, openai.ChatCompletionMessage{
			Role:    m.Role,
			Content: m.Content,
		})
	}

	return chatGPTMessages
}

func (c ChatGPT) send(ctx context.Context, messages []openai.ChatCompletionMessage) (*domain.LlmAnswer, error) {

	resp, err := c.client.CreateChatCompletion(ctx, openai.ChatCompletionRequest{
		Model:    c.model,
		Messages: messages,
	})
	if err != nil {
		return nil, err
	}

	if choices := resp.Choices; len(choices) == 0 {
		return nil, errors.New("got empty ChatGPT response")
	}

	answer := c.convertLlmAnswer(resp)
	return answer, nil
}

func (c ChatGPT) convertLlmAnswer(openaiResp openai.ChatCompletionResponse) *domain.LlmAnswer {

	choices := openaiResp.Choices[0]

	return &domain.LlmAnswer{
		Role:    choices.Message.Role,
		Content: choices.Message.Content,
	}
}
